/** void FieldGetPlayerInput(struct FieldInput *input, u16 newKeys, u16 heldKeys) */
export function FieldGetPlayerInput(input: any, newKeys: any, heldKeys: any): any {
  let tileTransitionState: any = gPlayerAvatar.tileTransitionState;
      let runningState: any = gPlayerAvatar.runningState;
      let forcedMove: any = MetatileBehavior_IsForcedMovementTile(GetPlayerCurMetatileBehavior(runningState));

      if ((tileTransitionState == T_TILE_CENTER && forcedMove == FALSE) || tileTransitionState == T_NOT_MOVING)
      {
          if (GetPlayerSpeed() != PLAYER_SPEED_FASTEST)
          {
              if (newKeys & START_BUTTON)
                  input.pressedStartButton = TRUE;
              if (newKeys & SELECT_BUTTON)
                  input.pressedSelectButton = TRUE;
              if (newKeys & A_BUTTON)
                  input.pressedAButton = TRUE;
              if (newKeys & B_BUTTON)
                  input.pressedBButton = TRUE;
          }

          if (heldKeys & (DPAD_UP | DPAD_DOWN | DPAD_LEFT | DPAD_RIGHT))
          {
              input.heldDirection = TRUE;
              input.heldDirection2 = TRUE;
          }
      }

      if (forcedMove == FALSE)
      {
          if (tileTransitionState == T_TILE_CENTER && runningState == MOVING)
              input.tookStep = TRUE;
          if (forcedMove == FALSE && tileTransitionState == T_TILE_CENTER)
              input.checkStandardWildEncounter = TRUE;
      }

      if (heldKeys & DPAD_UP)
          input.dpadDirection = DIR_NORTH;
      else if (heldKeys & DPAD_DOWN)
          input.dpadDirection = DIR_SOUTH;
      else if (heldKeys & DPAD_LEFT)
          input.dpadDirection = DIR_WEST;
      else if (heldKeys & DPAD_RIGHT)
          input.dpadDirection = DIR_EAST;
}

/** int ProcessPlayerFieldInput(struct FieldInput *input) */
export function ProcessPlayerFieldInput(input: any): any {
  let position: any = null;
      let playerDirection: any = null;
      let metatileBehavior: any = null;

      gSpecialVar_LastTalked = LOCALID_NONE;
      gSelectedObjectEvent = 0;

      playerDirection = GetPlayerFacingDirection();
      GetPlayerPosition(position);
      metatileBehavior = MapGridGetMetatileBehaviorAt(position.x, position.y);

      if (CheckForTrainersWantingBattle() == TRUE)
          return TRUE;

      if (TryRunOnFrameMapScript() == TRUE)
          return TRUE;

      if (input.pressedBButton && TrySetupDiveEmergeScript() == TRUE)
          return TRUE;
      if (input.tookStep)
      {
          IncrementGameStat(GAME_STAT_STEPS);
          IncrementBirthIslandRockStepCount();
          if (TryStartStepBasedScript(position, metatileBehavior, playerDirection) == TRUE)
              return TRUE;
      }
      if (input.checkStandardWildEncounter && CheckStandardWildEncounter(metatileBehavior) == TRUE)
          return TRUE;
      if (input.heldDirection && input.dpadDirection == playerDirection)
      {
          if (TryArrowWarp(position, metatileBehavior, playerDirection) == TRUE)
              return TRUE;
      }

      GetInFrontOfPlayerPosition(position);
      metatileBehavior = MapGridGetMetatileBehaviorAt(position.x, position.y);
      if (input.pressedAButton && TryStartInteractionScript(position, metatileBehavior, playerDirection) == TRUE)
          return TRUE;

      if (input.heldDirection2 && input.dpadDirection == playerDirection)
      {
          if (TryDoorWarp(position, metatileBehavior, playerDirection) == TRUE)
              return TRUE;
      }
      if (input.pressedAButton && TrySetupDiveDownScript() == TRUE)
          return TRUE;
      if (input.pressedStartButton)
      {
          PlaySE(SE_WIN_OPEN);
          ShowStartMenu();
          return TRUE;
      }
      if (input.pressedSelectButton && UseRegisteredKeyItemOnField() == TRUE)
          return TRUE;

      return FALSE;
}

