/** static bool8 TryStartStepCountScript(u16 metatileBehavior) */
export function TryStartStepCountScript(metatileBehavior: any): any {
  if (InUnionRoom() == TRUE)
      {
          return FALSE;
      }

      IncrementRematchStepCounter();
      UpdateFriendshipStepCounter();
      UpdateFarawayIslandStepCounter();

      if (!(gPlayerAvatar.flags & PLAYER_AVATAR_FLAG_FORCED_MOVE) && !MetatileBehavior_IsForcedMovementTile(metatileBehavior))
      {
          if (UpdatePoisonStepCounter() == TRUE)
          {
              ScriptContext_SetupScript(EventScript_FieldPoison);
              return TRUE;
          }
          if (ShouldEggHatch())
          {
              IncrementGameStat(GAME_STAT_HATCHED_EGGS);
              ScriptContext_SetupScript(EventScript_EggHatch);
              return TRUE;
          }
          if (AbnormalWeatherHasExpired() == TRUE)
          {
              ScriptContext_SetupScript(AbnormalWeather_EventScript_EndEventAndCleanup_1);
              return TRUE;
          }
          if (ShouldDoBrailleRegicePuzzle() == TRUE)
          {
              ScriptContext_SetupScript(IslandCave_EventScript_OpenRegiEntrance);
              return TRUE;
          }
          if (ShouldDoWallyCall() == TRUE)
          {
              ScriptContext_SetupScript(MauvilleCity_EventScript_RegisterWallyCall);
              return TRUE;
          }
          if (ShouldDoScottFortreeCall() == TRUE)
          {
              ScriptContext_SetupScript(Route119_EventScript_ScottWonAtFortreeGymCall);
              return TRUE;
          }
          if (ShouldDoScottBattleFrontierCall() == TRUE)
          {
              ScriptContext_SetupScript(LittlerootTown_ProfessorBirchsLab_EventScript_ScottAboardSSTidalCall);
              return TRUE;
          }
          if (ShouldDoRoxanneCall() == TRUE)
          {
              ScriptContext_SetupScript(RustboroCity_Gym_EventScript_RegisterRoxanne);
              return TRUE;
          }
          if (ShouldDoRivalRayquazaCall() == TRUE)
          {
              ScriptContext_SetupScript(MossdeepCity_SpaceCenter_2F_EventScript_RivalRayquazaCall);
              return TRUE;
          }
      }

      if (SafariZoneTakeStep() == TRUE)
          return TRUE;
      if (CountSSTidalStep(1) == TRUE)
      {
          ScriptContext_SetupScript(SSTidalCorridor_EventScript_ReachedStepCount);
          return TRUE;
      }
      if (TryStartMatchCall())
          return TRUE;
      return FALSE;
}

/** static void UpdateFriendshipStepCounter(void) */
export function UpdateFriendshipStepCounter(): any {
  let ptr: any = GetVarPointer(VAR_FRIENDSHIP_STEP_COUNTER);
      let i: any = null;

      ptr++;
      ptr %= 128;
      if (ptr == 0)
      {
          let mon: any = gPlayerParty;
          for (i = 0; i < PARTY_SIZE; i++)
          {
              AdjustFriendship(mon, FRIENDSHIP_EVENT_WALKING);
              mon++;
          }
      }
}

/** void ClearPoisonStepCounter(void) */
export function ClearPoisonStepCounter(): any {
  VarSet(VAR_POISON_STEP_COUNTER, 0);
}

/** static bool8 UpdatePoisonStepCounter(void) */
export function UpdatePoisonStepCounter(): any {
  let ptr: any = null;

      if (gMapHeader.mapType != MAP_TYPE_SECRET_BASE)
      {
          ptr = GetVarPointer(VAR_POISON_STEP_COUNTER);
          ptr++;
          ptr %= 4;
          if (ptr == 0)
          {
              switch (DoPoisonFieldEffect())
              {
              case FLDPSN_NONE:
                  return FALSE;
              case FLDPSN_PSN:
                  return FALSE;
              case FLDPSN_FNT:
                  return TRUE;
              }
          }
      }
      return FALSE;
}

/** void RestartWildEncounterImmunitySteps(void) */
export function RestartWildEncounterImmunitySteps(): any {
  sWildEncounterImmunitySteps = 0;
}

/** static bool8 CheckStandardWildEncounter(u16 metatileBehavior) */
export function CheckStandardWildEncounter(metatileBehavior: any): any {
  if (sWildEncounterImmunitySteps < 4)
      {
          sWildEncounterImmunitySteps++;
          sPrevMetatileBehavior = metatileBehavior;
          return FALSE;
      }

      if (StandardWildEncounter(metatileBehavior, sPrevMetatileBehavior) == TRUE)
      {
          sWildEncounterImmunitySteps = 0;
          sPrevMetatileBehavior = metatileBehavior;
          return TRUE;
      }

      sPrevMetatileBehavior = metatileBehavior;
      return FALSE;
}

