/** static void SetupWarp(struct MapHeader *unused, s8 warpEventId, struct MapPosition *position) */
export function SetupWarp(unused: any, warpEventId: any, position: any): any {
  let warpEvent: any = null;

      let trainerHillMapId: any = GetCurrentTrainerHillMapId();

      if (trainerHillMapId)
      {
          if (trainerHillMapId == GetNumFloorsInTrainerHillChallenge())
          {
              if (warpEventId == 0)
                  warpEvent =gMapHeader.events.warps[0];
              else
                  warpEvent = SetWarpDestinationTrainerHill4F();
          }
          else if (trainerHillMapId == TRAINER_HILL_ROOF)
          {
              warpEvent = SetWarpDestinationTrainerHillFinalFloor(warpEventId);
          }
          else
          {
              warpEvent =gMapHeader.events.warps[warpEventId];
          }
      }
      else
      {
          warpEvent =gMapHeader.events.warps[warpEventId];
      }

      if (warpEvent.mapNum == MAP_NUM(MAP_DYNAMIC))
      {
          SetWarpDestinationToDynamicWarp(warpEvent.warpId);
      }
      else
      {
          let mapHeader: any = null;

          SetWarpDestinationToMapWarp(warpEvent.mapGroup, warpEvent.mapNum, warpEvent.warpId);
          UpdateEscapeWarp(position.x, position.y);
          mapHeader = Overworld_GetMapHeaderByGroupAndId(warpEvent.mapGroup, warpEvent.mapNum);
          if (mapHeader.events.warps[warpEvent.warpId].mapNum == MAP_NUM(MAP_DYNAMIC))
              SetDynamicWarp(mapHeader.events.warps[warpEventId].warpId, gSaveBlock1Ptr.location.mapGroup, gSaveBlock1Ptr.location.mapNum, warpEventId);
      }
}

/** static bool8 TryDoorWarp(struct MapPosition *position, u16 metatileBehavior, u8 direction) */
export function TryDoorWarp(position: any, metatileBehavior: any, direction: any): any {
  let warpEventId: any = null;

      if (direction == DIR_NORTH)
      {
          if (MetatileBehavior_IsOpenSecretBaseDoor(metatileBehavior) == TRUE)
          {
              WarpIntoSecretBase(position, gMapHeader.events);
              return TRUE;
          }

          if (MetatileBehavior_IsWarpDoor(metatileBehavior) == TRUE)
          {
              warpEventId = GetWarpEventAtMapPosition(gMapHeader, position);
              if (warpEventId != WARP_ID_NONE && IsWarpMetatileBehavior(metatileBehavior) == TRUE)
              {
                  StoreInitialPlayerAvatarState();
                  SetupWarp(gMapHeader, warpEventId, position);
                  DoDoorWarp();
                  return TRUE;
              }
          }
      }
      return FALSE;
}

/** static s8 GetWarpEventAtPosition(struct MapHeader *mapHeader, u16 x, u16 y, u8 elevation) */
export function GetWarpEventAtPosition(mapHeader: any, x: any, y: any, elevation: any): any {
  let i: any = null;
      let warpEvent: any = mapHeader.events.warps;
      let warpCount: any = mapHeader.events.warpCount;

      for (i = 0; i < warpCount; i++, warpEvent++)
      {
          if (warpEvent.x == x && warpEvent.y == y)
          {
              if (warpEvent.elevation == elevation || warpEvent.elevation == ELEVATION_TRANSITION)
                  return i;
          }
      }
      return WARP_ID_NONE;
}

/** bool8 TryDoDiveWarp(struct MapPosition *position, u16 metatileBehavior) */
export function TryDoDiveWarp(position: any, metatileBehavior: any): any {
  if (gMapHeader.mapType == MAP_TYPE_UNDERWATER && !MetatileBehavior_IsUnableToEmerge(metatileBehavior))
      {
          if (SetDiveWarpEmerge(position.x - MAP_OFFSET, position.y - MAP_OFFSET))
          {
              StoreInitialPlayerAvatarState();
              DoDiveWarp();
              PlaySE(SE_M_DIVE);
              return TRUE;
          }
      }
      else if (MetatileBehavior_IsDiveable(metatileBehavior) == TRUE)
      {
          if (SetDiveWarpDive(position.x - MAP_OFFSET, position.y - MAP_OFFSET))
          {
              StoreInitialPlayerAvatarState();
              DoDiveWarp();
              PlaySE(SE_M_DIVE);
              return TRUE;
          }
      }
      return FALSE;
}

/** u8 TrySetDiveWarp(void) */
export function TrySetDiveWarp(): any {
  let x, y;
      let metatileBehavior: any = null;

      PlayerGetDestCoords(x,y);
      metatileBehavior = MapGridGetMetatileBehaviorAt(x, y);
      if (gMapHeader.mapType == MAP_TYPE_UNDERWATER && !MetatileBehavior_IsUnableToEmerge(metatileBehavior))
      {
          if (SetDiveWarpEmerge(x - MAP_OFFSET, y - MAP_OFFSET) == TRUE)
              return 1;
      }
      else if (MetatileBehavior_IsDiveable(metatileBehavior) == TRUE)
      {
          if (SetDiveWarpDive(x - MAP_OFFSET, y - MAP_OFFSET) == TRUE)
              return 2;
      }
      return 0;
}

/** int SetCableClubWarp(void) */
export function SetCableClubWarp(): any {
  let position: any = null;

      GetPlayerMovementDirection();   
      GetPlayerPosition(position);
      MapGridGetMetatileBehaviorAt(position.x, position.y);   
      SetupWarp(gMapHeader, GetWarpEventAtMapPosition(gMapHeader,position),position);
      return 0;
}

